import manifest from './image-manifest.json';

/**
 * Bundled photos are stored as "/img/hall-a.jpg" (database rows and seed data keep that name) but shipped as responsive
 * AVIF + WebP files generated by `scripts/optimize-images.mjs`. This maps the old name to the variants.
 * Uploaded photos (Vercel Blob / local uploads) are already re-encoded to WebP at upload time and are used as they are.
 */
const M = manifest as Record<string, number[]>;

export type Variants = { avif: string; webp: string; fallback: string; widths: number[] };

export function bundledVariants(src: string): Variants | null {
  const m = /^\/img\/((?:avatars\/)?[\w-]+)\.(?:jpe?g|png)$/.exec(src);
  const widths = m && M[m[1]];
  if (!m || !widths) return null;
  const set = (ext: string) => widths.map((w) => `/img/${m[1]}-${w}.${ext} ${w}w`).join(', ');
  const mid = widths.find((w) => w >= 800) ?? widths[widths.length - 1];
  return { avif: m[1].startsWith('avatars/') ? '' : set('avif'), webp: set('webp'), fallback: `/img/${m[1]}-${mid}.webp`, widths };
}

/** Plain URL of the best single file for places that cannot use <picture> (e.g. CSS backgrounds, OG tags). */
export function bundledSingle(src: string, width = 1280): string {
  const v = bundledVariants(src);
  if (!v) return src;
  const w = v.widths.find((x) => x >= width) ?? v.widths[v.widths.length - 1];
  return v.fallback.replace(/-\d+\.webp$/, `-${w}.webp`);
}
